export function getProductSpecifications(slug, language = 'es') {
  const lang = language?.startsWith('es') ? 'es' : 'en'
  return (
    productSpecificationsBySlug[slug]?.[lang] ??
    getDummyProductSpecifications(slug, lang)
  )
}
